style.css:
@-moz-document domain("google.com") {
body {
    background-image: url("https://i.postimg.cc/FsTyZ6xH/18a2629959bebdce36a5e5be5bdbb6b7.gif");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center center;
  }

  /* Make background visible */
  #viewport, #main, .sfbg {
    background: transparent !important;
  }

  /* Optional: Make the Google logo and search box stand out */
  input, .RNmpXc, .gbqfbb, .gbqfba {
    background-color: rgba(0, 0, 0, 0.5) !important;
    color: white !important;
    border: none !important;
  }

  /* Optional: dim the GIF slightly for readability */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.3);
    z-index: -1;
  }
}
